resources.afterResponseScript:
// PASO 1 ya se ejecuto: esta es la respuesta de authentication-result.
// PASO 2 y PASO 3 se encadenan aqui mismo, igual que en Bruno / biometria_api.py:
//   2) GET documents-to-sign/{caso}
//   3) POST documents-signed/{caso} reenviando el generatedDocument (base64)
// NOTA: el sandbox de scripts de Insomnia no expone axios ni modulos nativos de
// Node (require('https') falla con "no module is found for https"). La unica
// forma soportada de disparar peticiones adicionales desde el script es
// insomnia.sendRequest (equivalente a pm.sendRequest de Postman).
const BASE = "https://platform-test-internal.colsubsidio.com/loans/identity/internal/v1/validator";
const API_KEY = "ecn24ysGnZ4X17cU5lX4Q9gyFvyPR7fD1DkwR7I7";
const ADOTECH_TRANSACTION = "2895";
const MATRICULA_ID = "61700";
const NOMBRES_DOCUMENTOS = ["INFORME_SOL_ONLINE_CERT", "PAGARE_ONLINE_CERT"];

function httpRequest(method, url, jsonBody) {
  const options = {
    url: url,
    method: method,
    header: {
      "content-type": "application/json",
      "accept": "application/json",
      "x-api-key": API_KEY
    }
  };
  if (jsonBody !== undefined) {
    options.body = { mode: "raw", raw: JSON.stringify(jsonBody) };
  }
  return new Promise((resolve, reject) => {
    insomnia.sendRequest(options, (err, response) => {
      if (err) return reject(err);
      let data = null;
      try { data = response.json(); } catch (e) {
        try { data = response.text(); } catch (e2) { /* deja null */ }
      }
      resolve({ status: response.code, data: data });
    });
  });
}

// Lee el body que se envio en el Paso 1 (ahi se edita caso/cedula, igual que en Bruno).
let rawBody = "";
try {
  const b = insomnia.request.body;
  rawBody = (b && (b.text || b.raw)) || (typeof b === "string" ? b : "");
} catch (e) { /* ignora, cae a {} */ }
let bodyEnviado = {};
try { bodyEnviado = JSON.parse(rawBody); } catch (e) { bodyEnviado = {}; }

const noti = ((bodyEnviado && bodyEnviado.notificacion) || [])[0] || {};
const caso = String((noti.proceso || {}).codigo || "");
const cedula = String((noti.documento || {}).numero || "");

const paso1Status = insomnia.response.code;
let paso1Body = "";
try { paso1Body = insomnia.response.body ? insomnia.response.body.toString() : ""; } catch (e) {}

const resumen = {
  resultado: "",
  caso: caso,
  cedula: cedula,
  paso1_autenticacion: "HTTP " + paso1Status,
  paso2_documentos: "no se ejecuto",
  paso3_firma: "no se ejecuto"
};
let pasoFallido = null;
let paso2Status = null, paso2Docs = 0, paso3Status = null;

async function correr() {
  if (paso1Status !== 200) {
    pasoFallido = 1;
    resumen.respuesta_paso1 = paso1Body;
  } else {
    const r2 = await httpRequest("GET", BASE + "/documents-to-sign/" + caso);
    const docs = Array.isArray(r2.data) ? r2.data : [];
    paso2Status = r2.status;
    paso2Docs = docs.length;
    resumen.paso2_documentos = "HTTP " + r2.status + " (" + docs.length + " documento(s))";

    if (r2.status !== 200 || docs.length === 0) {
      pasoFallido = 2;
      resumen.respuesta_paso2 = r2.data;
    } else {
      const firmados = docs.slice(0, 2).map((doc, i) => ({
        documentoBase64: doc.generatedDocument || "",
        nombre: NOMBRES_DOCUMENTOS[i] || doc.name || "DOC_" + i,
        tipoDocumento: 1
      }));
      const body3 = {
        tipoDocumento: "4",
        adotechTransaction: ADOTECH_TRANSACTION,
        matriculaId: MATRICULA_ID,
        idProceso: caso,
        nroDocumento: cedula,
        documentosFirmadosResponsable: firmados
      };
      const r3 = await httpRequest("POST", BASE + "/documents-signed/" + caso, body3);
      paso3Status = r3.status;
      resumen.paso3_firma = "HTTP " + r3.status;
      resumen.respuesta_paso3 = r3.data;
      if (r3.status !== 200) pasoFallido = 3;
    }
  }

  resumen.resultado = pasoFallido ? "BIOMETRIA FALLO en paso " + pasoFallido : "BIOMETRIA OK";

  insomnia.environment.set("paso1Status", paso1Status);
  insomnia.environment.set("paso2Status", paso2Status);
  insomnia.environment.set("paso2Docs", paso2Docs);
  insomnia.environment.set("paso3Status", paso3Status);
  insomnia.environment.set("resumen", JSON.stringify(resumen));

  // Insomnia no permite reemplazar el body mostrado en la pestana Response
  // (a diferencia de res.setBody en Bruno): el resumen queda en consola y
  // en la variable de entorno "resumen" para revisarlo ahi.
  console.log("RESUMEN BIOMETRIA:\n" + JSON.stringify(resumen, null, 2));

  insomnia.test("Paso 1/3 autenticacion biometrica -> 200", () => {
    insomnia.expect(paso1Status).to.equal(200);
  });
  insomnia.test("Paso 2/3 documentos a firmar -> 200 con al menos 1 documento", () => {
    insomnia.expect(paso2Status).to.equal(200);
    insomnia.expect(paso2Docs).to.be.above(0);
  });
  insomnia.test("Paso 3/3 documentos firmados -> 200", () => {
    insomnia.expect(paso3Status).to.equal(200);
  });
}

await correr();
